p = os.path.join(D, 'era-blurbs.json')
d = json.load(open(p))
for y, t in H.items(): d[str(y)] = t
json.dump(d, open(p, 'w'), indent=0, ensure_ascii=False)
print(len(H), 'blurbs merged')
